# Idempotency (fixed 2026-08-04, session 0a). This script OWNS confirmed_facts -
# build_index.py creates the table and nothing else inserts into it - so clearing
# first makes a standalone re-run safe. Without this, running the seeder twice
# without an intervening build_index.py rebuild DOUBLES every fact (observed live:
# 103 -> 213 rows). Same bug class as the two found in build_dbc_index.py today.
cur.execute('DELETE FROM confirmed_facts')

cur.executemany('INSERT INTO confirmed_facts (topic, fact, source_doc, source_section) VALUES (?,?,?,?)',
                 [(t, f, d, s) for (t, f, d, s) in FACTS])

conn.commit()
cur.execute('SELECT COUNT(*) FROM spells WHERE class_origin IS NOT NULL')
print('spells with confirmed class_origin:', cur.fetchone()[0])
cur.execute('SELECT COUNT(*) FROM confirmed_facts')
print('confirmed_facts rows:', cur.fetchone()[0])
conn.close()
